
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_5_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_5", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.712306954575681e+00, -4.619750100842796e+00, -4.490102238568521e+00, -4.310602817248026e+00, -4.066201811564920e+00, -3.741279943885835e+00, -3.323625900676623e+00, -2.811007334475391e+00, -2.217079506813413e+00, -1.571726021716454e+00, -9.795089991925414e-01, -6.791576923128035e-01, -6.145508472234248e-01, -5.195683064839437e-01, -3.691984689709569e-01, -2.179756116598463e-01, -1.003005665503926e-01, -3.360778416790233e-02, -7.229722786540438e-03, -8.139726989286278e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


